STORY = [('baek_mom', '너 어제 회사에서 밤샌 거 아니었어? 왜 거기서 나와?', "Didn't you stay up all night at work yesterday? Why are you coming out of there?", [(170, '너 어제 회사에서 밤샌 거 아니었어'), (171, '왜 거기서 나와')], ''), ('seungchan', '회사 선배님 댁이 바로 여기 앞동이라서요.', 'Because a senior colleague from work lives right in this building.', [(172, '회사 선배님 댁이 바로 여기 앞동')], ''), ('baek_mom', '집을 코앞에 두고 남의 집에서 잤어?', "With your own home right under your nose, you slept at someone else's place?", [(175, '집을 코앞에 두고 남의 집에서 잤어')], ''), ('baek_mom', '안 그래도 너한테 할 말 있었는데 잘 만났다.', 'I actually had something to tell you anyway, so I am glad I ran into you.', [(182, '잘 만났다'), (183, '안 그래도 너한테 할 말 있었는데')], ''), ('seungchan', '왜? 무슨 일 있어?', 'Why? What is going on?', [(184, '왜')], ''), ('baek_mom', '네 매형 병원이 요새 되게 힘들다.', "Your brother-in-law's clinic is having a really hard time lately.", [(185, '네 매형 병원이 요새 되게 힘들다')], ''), ('baek_mom', '바로 길 건너에 비뇨기과가 새로 열었거든.', 'A new urology clinic just opened right across the street.', [(186, '바로 길 건너에 비뇨기과가 새로')], ''), ('baek_mom', '니네 방송국 건강 프로그램에 네 매형 좀 출연시켜 봐.', 'Try getting your brother-in-law onto that health program at your station.', [(198, '니네 방송국에'), (199, '네 매형 좀 출연시켜줘봐')], ''), ('baek_mom', '병원 문 닫고 네 매형 백수 되게 생겼다니까.', 'The clinic is about to close and turn your brother-in-law into an unemployed man.', [(210, '병원 문 닫고 네 매형 백수되게 생겼다니까')], ''), ('seungchan', '매형보다 내가 먼저 백수 될 수도 있어.', 'I might end up unemployed even before my brother-in-law does.', [(212, '매형보다 내가 먼저 백수될 수도 있어')], ''), ('seungchan', '수습 기간 중에 세 번 사고 치면 잘릴 수도 있대요.', 'I heard that if you cause trouble three times during probation, you can get fired.', [(215, '수습기간 중에'), (217, '잘릴 수도 있다고 들었는데요')], ''), ('seungchan', '벌써 두 번 사고 친 것 같아서 간당간당한 느낌이에요.', 'I feel like I already messed up twice, so I am hanging by a thread.', [(218, '사고친 것 같아서'), (219, '간당간당한 느낌')], '')]
